    padding: 80px 0;
    margin-bottom: 40px;
}

.hero-section h2 {
    color: var(--accent-color);
    font-size: 3em;
    margin-bottom: 20px;
}

.hero-section p {
    max-width: 800px;
    margin: 0 auto 30px auto;
    font-size: 1.1em;
}

.search-area {
    background-color: rgba(255, 255, 255, 0.9);
    border-radius: 8px;
    padding: 20px 30px;
    display: inline-block; /* Makes it shrink to content width */
    max-width: 600px;
    box-shadow: 0 4px 15px var(--shadow-light);
}

.search-area form {
    display: flex;
    gap: 10px;
}

.search-area input[type="text"] {
    flex-grow: 1;
    padding: 12px 15px;
    border: 1px solid var(--border-color);
    border-radius: 5px;
    font-size: 1em;
    font-family: 'Arial', sans-serif;
}

.search-area button {
    background-color: var(--secondary-color);
    color: var(--text-light);
    padding: 12px 25px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 1em;
    font-weight: bold;
    transition: background-color 0.3s ease;
}

.search-area button:hover {
    background-color: var(--primary-color);
}

.featured-artifacts {
    padding: 40px 0;
    text-align: center;
}

.featured-artifacts h3 {
    margin-bottom: 30px;
    color: var(--primary-color);
}

.artifact-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 30px;
    margin-bottom: 40px;
}

.artifact-card {
    background-color: #fff;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 2px 10px var(--shadow-light);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.artifact-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.15);
}

.artifact-card a {
    display: block;
    color: var(--text-dark);
    text-decoration: none;
}

.artifact-card img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
}

.artifact-card h4 {
    margin: 15px 15px 5px 15px;
    color: var(--primary-color);
    font-size: 1.1em;
}

.artifact-card p {
    margin: 0 15px 15px 15px;
    font-size: 0.9em;
    color: #666;
}

.browse-link .button {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--primary-color);
    padding: 12px 30px;
    border-radius: 5px;
    font-weight: bold;
    text-decoration: none;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.browse-link .button:hover {
    background-color: var(--secondary-color);
    color: var(--text-light);
}

/* Artifact Page Specific Styles */
.artifact-main {
    flex-grow: 1;
    padding: 40px 0;
}

.breadcrumb {
    margin-bottom: 20px;
    font-size: 0.9em;
    color: #777;
}

.breadcrumb a {
    color: #777;
}

.breadcrumb a:hover {
    color: var(--secondary-color);
}

.artifact-detail-header {
    border-bottom: 2px solid var(--border-color);
    padding-bottom: 15px;
    margin-bottom: 30px;
}

.artifact-detail-header h2 {
    font-size: 2.5em;
    margin-bottom: 5px;
}

.artifact-id {
    color: #888;
    font-style: italic;
    font-size: 0.9em;
}

.artifact-content-wrapper {
    display: flex;
    gap: 40px;
    flex-wrap: wrap; /* Allows wrapping on smaller screens */
}

.artifact-media {
    flex: 1;
    min-width: 300px; /* Minimum width before wrapping */
}

.main-image {
    margin-bottom: 15px;
    text-align: center;
}

.large-artifact-photo {
    max-width: 100%;
    height: auto;
    border: 1px solid var(--border-color);
    border-radius: 5px;
    box-shadow: 0 2px 8px var(--shadow-light);
}

.artifact-media .caption {
    font-size: 0.9em;
    color: #666;
    margin-top: 10px;
}

.thumbnail-gallery {
    display: flex;
    justify-content: center;
    gap: 10px;
    margin-top: 20px;
    flex-wrap: wrap;
}

.thumbnail-gallery img {
    width: 100px;
    height: 70px;
    object-fit: cover;
    border: 2px solid var(--border-color);
    border-radius: 4px;
    cursor: pointer;
    transition: border-color 0.2s ease, transform 0.2s ease;
