}

.artifact-description ul li strong {
    color: var(--primary-color);
}

.location-map {
    text-align: center;
    margin-top: 30px;
    border: 1px solid var(--border-color);
    border-radius: 5px;
    overflow: hidden;
    padding: 10px;
    background-color: #fcfcfc;
}

.location-map img {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 0 auto;
    border-radius: 3px;
}

.location-map .caption {
    font-size: 0.85em;
    color: #777;
    margin-top: 10px;
}

.navigation-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
    padding-top: 20px;
    border-top: 1px dashed var(--border-color);
}

.navigation-buttons .button {
    background-color: var(--secondary-color);
    color: var(--text-light);
    padding: 10px 20px;
    border-radius: 5px;
    font-weight: bold;
    text-decoration: none;
    transition: background-color 0.3s ease;
}

.navigation-buttons .button:hover {
    background-color: var(--primary-color);
}


/* Footer */
.site-footer {
    background-color: var(--primary-color);
    color: var(--text-light);
    text-align: center;
    padding: 25px 0;
    margin-top: auto; /* Pushes footer to bottom */
    font-size: 0.9em;
}

.site-footer p {
    margin: 0 0 5px 0;
}


/* Responsive Adjustments */
@media (max-width: 768px) {
    .site-header .container {
        flex-direction: column;
        text-align: center;
    }
    .site-header nav ul {
        margin-top: 15px;
        justify-content: center;
    }
    .site-header nav ul li {
        margin: 0 10px;
    }

    .hero-section {
        padding: 60px 0;
    }
    .hero-section h2 {
        font-size: 2.2em;
    }
    .hero-section p {
        font-size: 1em;
    }
    .search-area form {
        flex-direction: column;
    }
    .search-area button {
        width: 100%;
    }

    .artifact-grid {
        grid-template-columns: 1fr; /* Single column on smaller screens */
    }

    .artifact-content-wrapper {
        flex-direction: column; /* Stack media and description */
        gap: 30px;
    }
    .artifact-media, .artifact-description {
        min-width: unset; /* Remove min-width for stacking */
