    }

    .search-area {
        padding: 15px;
    }
    .search-area input[type="text"] {
        padding: 10px;
    }
    .search-area button {
        padding: 10px;
    }

    .artifact-detail-header h2 {
        font-size: 2em;
    }
    .artifact-description {
        padding: 20px;
    }
}
